let currentUser=null,accountDemo=true;
const accountEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function preferencesKey(){return 'week-meal-settings-v2:'+currentUser.id+':'+currentUser.city?.id}
async function accountRequest(path,body){if(currentUser?.guest&&path==='profile/city'){const city=guestCities.find(c=>c.id===body.id);if(!city)throw Error('Выберите город из списка');currentUser.city=city;localStorage.setItem('meal-guest',JSON.stringify(currentUser));return {user:currentUser}}const r=await fetch('/api/'+path,{credentials:currentUser?.guest?'omit':'same-origin',method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const j=await r.json();if(!r.ok)throw Error(j.error||'Не удалось выполнить запрос');return j}
function accountPage(html){$('#footer').hidden=true;$('#navigation').hidden=true;$('#header').innerHTML='<span class="header-logo">нямба<b>✦</b></span>';$('#screen').innerHTML='<section class="enter account-page">'+html+'<p id="account-error" role="alert"></p></section>';window.scrollTo(0,0)}
async function accountAction(button,fn){button.disabled=true;try{await fn()}catch(e){const el=$('#account-error');if(el)el.textContent=e.message}finally{button.disabled=false}}
async function accountStart(){try{if(location.hostname==="appassets.androidplatform.net"){enterGuest();return}if(localStorage.getItem("meal-guest-active")==="1"){enterGuest();return}const j=await accountRequest('auth/me');currentUser=j.user;accountDemo=j.demo;if(!currentUser)renderLogin();else if(!currentUser.city)renderCity();else bootApp()}catch{accountPage('<h1>Подключимся?</h1><p>Для входа нужен запущенный сервер приложения и соединение.</p><button class="primary" onclick="accountStart()">Повторить</button><button class="outline-button" onclick="enterGuest()">Продолжить как гость</button>')}}
function renderLogin(){accountPage('<div class="welcome-art"><span class="art-label">ВКУСНО. ПРОСТО. ПО ПЛАНУ.</span><img src="food-art.svg" alt="Декоративная иллюстрация блюда"></div><div class="eyebrow">Нямба · ваш план питания</div><h1>Привет!<br>Что приготовим?</h1><p class="intro">Войдите по номеру телефона.<br>Потом выберем город и магазины.</p><form id="phone-form"><label for="phone">Номер телефона</label><input id="phone" type="tel" autocomplete="tel" placeholder="+7 900 000-00-00" required maxlength="30"><button class="primary">Получить код →</button></form><button class="outline-button" onclick="enterGuest()">Продолжить как гость →</button><p class="note">Гостевые настройки и меню сохраняются только в этом браузере. Очистка данных браузера удалит их.</p>'+(accountDemo?'<div class="demo-box">Тестовый вход: SMS не отправляется. Покажем код здесь. Такой вход не подтверждает владение номером. Используйте тестовый номер.</div>':''));$('#phone-form').onsubmit=e=>{e.preventDefault();accountAction(e.submitter,async()=>renderCode(await accountRequest('auth/code',{phone:$('#phone').value})))}}
function renderCode(challenge){accountPage('<div class="eyebrow">'+(challenge.demo?'Тестовый вход':'Подтверждение номера')+'</div><h1>Введите код</h1><p>'+accountEscape(challenge.phone)+'</p>'+(challenge.demo?'<div class="demo-box">SMS не отправлено. Тестовый код: <b id="test-code">'+accountEscape(challenge.testCode)+'</b></div>':'<p>Код отправлен по SMS.</p>')+'<form id="code-form"><label for="code">Код из 6 цифр</label><input id="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required><button class="primary">Войти →</button></form><p class="note">Код действует 5 минут. Новый можно запросить через минуту.</p><button id="resend" class="text-button">Запросить новый код</button><button id="another-phone" class="text-button">Другой номер</button>');$('#code-form').onsubmit=e=>{e.preventDefault();accountAction(e.submitter,async()=>{const j=await accountRequest('auth/verify',{challengeId:challenge.challengeId,code:$('#code').value});currentUser=j.user;if(currentUser.city)bootApp();else renderCity()})};$('#resend').onclick=e=>accountAction(e.target,async()=>renderCode(await accountRequest('auth/code',{phone:challenge.phone})));$('#another-phone').onclick=renderLogin}
function renderCity(){accountPage('<div class="eyebrow">Ближе к дому</div><h1>В каком городе<br>будем покупать?</h1><form id="city-form"><label for="city">Город</label><input id="city" value="'+accountEscape(currentUser.city?.name||'Воронеж')+'" required minlength="2"><button class="primary">Найти город</button></form><div id="city-results"></div><p class="note">Поиск: Open-Meteo · GeoNames</p>');$('#city-form').onsubmit=e=>{e.preventDefault();accountAction(e.submitter,async()=>{const j=await accountRequest('cities?q='+encodeURIComponent($('#city').value));guestCities=j.cities;$('#city-results').innerHTML=j.cities.length?j.cities.map(c=>'<button class="city-choice" data-city="'+c.id+'"><b>'+accountEscape(c.name)+'</b><small>'+accountEscape(c.region)+'</small><span>→</span></button>').join(''):'<p>Город не найден. Уточните название.</p>';document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>accountAction(b,async()=>{const j=await accountRequest('profile/city',{id:Number(b.dataset.city)});currentUser=j.user;storeCatalog={city:currentUser.city.name,items:[],sources:[]};catalogLoaded=false;realOffers={};Object.keys(products).forEach(k=>products[k]=structuredClone(demoProducts[k]));plan=undefined;state.priceMode='demo';renderNearby()}))})}}
function accountSettings(){return '<div class="settings-card"><small>'+accountEscape(currentUser?.guest?'Гость · данные в этом браузере':currentUser?.phone)+' · '+accountEscape(currentUser?.city?.name)+'</small><p><button id="nearby" class="text-button">Магазины на карте →</button></p><button id="change-city" class="text-button">Изменить город</button> · <button id="logout" class="text-button">Выйти</button></div>'}
function bindAccountSettings(){$('#nearby').onclick=renderNearby;$('#change-city').onclick=renderCity;$('#logout').onclick=async()=>{try{if(currentUser?.guest)localStorage.removeItem('meal-guest-active');else await accountRequest('auth/logout',{});location.reload()}catch(e){toast(e.message)}}}
async function renderNearby(){accountPage('<div class="eyebrow">'+accountEscape(currentUser.city.name)+'</div><h1>Магазины рядом</h1><p id="map-origin" class="note">Ищем в радиусе 5 км от центра города. Нажмите на карту, чтобы выбрать точку.</p><button id="locate" class="text-button">Определить моё местоположение</button><div id="store-map" aria-label="Карта ближайших магазинов"></div><button id="map-search" class="primary">Найти магазины здесь</button><p id="map-status" role="status"></p><div id="map-filters"></div><details class="store-disclosure"><summary>Магазины списком <span id="store-count"></span></summary><div id="store-list"></div></details><p class="note">Адреса: © OpenStreetMap contributors. Расстояния по прямой. Данные могут быть неполными. Карта не подтверждает наличие и цены товаров в этих магазинах.</p><button id="map-done" class="primary">Продолжить к меню →</button>');$('#map-done').onclick=()=>bootApp();let point={lat:currentUser.city.lat,lon:currentUser.city.lon},items=[],enabled=new Set([0,1,2,3,4]),map,layer,origin;const colors=['#cb343b','#cf333b','#2664bb','#32845c','#da4a35'];try{const config=await accountRequest('maps/config');if(!$('#store-map'))return;map=L.map('store-map').setView([point.lat,point.lon],13);L.tileLayer(config.tileUrl,{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);layer=L.layerGroup().addTo(map);origin=L.circleMarker([point.lat,point.lon],{radius:9,color:'#202825',fillOpacity:1}).addTo(map);map.on('click',e=>{request++;point={lat:e.latlng.lat,lon:e.latlng.lng};origin.setLatLng(e.latlng);layer.clearLayers();$('#store-list').innerHTML='';$('#map-search').disabled=false;$('#map-status').textContent='';$('#map-origin').textContent='Выбрана точка на карте. Нажмите «Найти магазины здесь».'});}catch(e){$('#account-error').textContent='Не удалось загрузить карту: '+e.message;return}
function draw(){if(!$('#store-list'))return;layer.clearLayers();const shown=items.filter(s=>enabled.has(s.chain));$('#store-count').textContent='· '+shown.length;$('#store-list').innerHTML=shown.map(s=>'<article class="city-choice"><b>'+accountEscape(s.name)+'</b><small>'+accountEscape(s.address)+' · '+(s.distanceMeters/1000).toFixed(1)+' км</small><a href="'+accountEscape(s.sourceUrl)+'" target="_blank" rel="noreferrer">На OpenStreetMap ↗</a></article>').join('')||'<p>В выбранных сетях магазины не найдены.</p>';shown.forEach(s=>L.circleMarker([s.lat,s.lon],{radius:7,color:colors[s.chain],fillOpacity:.85}).bindPopup(accountEscape(s.name)+'<br>'+accountEscape(s.address)).addTo(layer))}
$('#map-filters').innerHTML=shops.map((s,i)=>'<label><input type="checkbox" data-map-chain="'+i+'" checked>'+accountEscape(s[0])+'</label>').join('');document.querySelectorAll('[data-map-chain]').forEach(b=>b.onchange=()=>{b.checked?enabled.add(Number(b.dataset.mapChain)):enabled.delete(Number(b.dataset.mapChain));draw()});let request=0;async function search(){const seq=++request;$('#map-search').disabled=true;$('#map-status').textContent='Ищем реальные адреса…';try{const j=await accountRequest('maps/nearby?lat='+point.lat+'&lon='+point.lon);if(seq!==request||!$('#store-list'))return;items=j.items;draw();$('#map-status').textContent='Показано ближайших магазинов: '+items.length+' (до 150)' ;}catch(e){if($('#map-status'))$('#map-status').textContent=e.message}finally{if($('#map-search'))$('#map-search').disabled=false}}
$('#map-search').onclick=search;$('#locate').onclick=()=>{if(!navigator.geolocation){$('#map-status').textContent='Геолокация недоступна. Выберите точку на карте.';return}navigator.geolocation.getCurrentPosition(p=>{if(!$('#store-map'))return;point={lat:p.coords.latitude,lon:p.coords.longitude};origin.setLatLng([point.lat,point.lon]);map.setView([point.lat,point.lon],14);$('#map-origin').textContent='Поиск рядом с вашим местоположением.';search()},()=>{if($('#map-status'))$('#map-status').textContent='Местоположение не получено. Можно выбрать точку на карте.'},{timeout:10000,maximumAge:60000})};search()}

let guestCities=[];
function enterGuest(){try{const saved=JSON.parse(localStorage.getItem('meal-guest')||'null');currentUser={id:'guest',guest:true,city:saved?.city||{id:472045,name:'Воронеж',region:'Воронежская область',lat:51.66833,lon:39.19204}};localStorage.setItem('meal-guest',JSON.stringify(currentUser));localStorage.setItem('meal-guest-active','1');bootApp()}catch(e){accountPage('<h1>Не удалось сохранить</h1><p>Разрешите локальное хранилище браузера для гостевого режима.</p>')}}
